const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;color:var(--ink);font-family:system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;font-size:12px;line-height:1.3}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.card button:focus-visible,.card .in:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.app{display:flex;flex-direction:column;gap:6px;width:100%;height:100%;min-height:0;min-width:0;padding:8px}\n.hd{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.ht{flex:1;min-width:0}\n.ttl{font-size:15px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.add{flex:none;display:inline-flex;align-items:center;justify-content:center;gap:4px;min-width:34px;height:34px;padding:0 9px;border:0;border-radius:17px;background:var(--accent);color:var(--on-accent);font-weight:600}\n.add .pl{font-size:20px;line-height:1;margin-top:-2px}\n.add .at{display:none;font-size:13px}\n\n.stats{display:none;flex:none;gap:6px;flex-wrap:wrap}\n.chip{display:inline-flex;align-items:center;padding:3px 9px;border-radius:12px;background:var(--soft);color:var(--muted);font-size:11px;border:1px solid transparent}\n.chip.on{color:var(--ink);font-weight:600;border-color:var(--accent)}\n\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.row{position:relative;flex:none;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:6px;padding:6px 6px 6px 12px;border-radius:12px;background:var(--panel-paper);border:1px solid var(--line);overflow:hidden}\n.row::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--line)}\n.row.st-today::before,.row.st-new::before,.row.st-soon::before{background:var(--accent)}\n.row.st-over::before{background:#B4533A}\n.rmain{min-width:0;display:grid;grid-template-columns:minmax(0,1fr);gap:2px;padding:0;margin:0;border:0;background:none;text-align:left}\n.tl{display:flex;flex-direction:column;min-width:0;gap:1px}\n.nm{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.meta{display:none;flex-direction:column;font-size:11px;color:var(--muted);min-width:0}\n.meta span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tr{display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;min-width:0;font-size:11px;color:var(--muted)}\n.rel{display:inline-block;flex:none;padding:1px 7px;border-radius:9px;background:var(--soft);color:var(--ink);font-size:11px;font-weight:600;white-space:nowrap}\n.st-over .rel{background:#B4533A;color:#FFFFFF}\n.st-today .rel,.st-new .rel{background:var(--accent);color:var(--on-accent)}\n.nx{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.dfull{display:none}\n.dshort{display:inline}\n.go{flex:none;min-width:46px;height:38px;padding:0 10px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-weight:600;font-size:13px}\n.go:active,.add:active,.big:active{opacity:.8}\n\n.err{flex:none;padding:6px 8px;border-radius:8px;border-left:4px solid #B4533A;background:var(--soft);color:var(--ink);font-size:12px}\n\n.empty{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;padding:4px}\n.et{font-size:14px;font-weight:700}\n.ed{font-size:11px;color:var(--muted);max-width:30em}\n.big{flex:none;width:100%;min-height:40px;padding:8px 14px;border:0;border-radius:12px;background:var(--accent);color:var(--on-accent);font-weight:700;font-size:14px}\n.empty .big{width:auto;min-width:130px}\n\n.bar{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.back{flex:none;height:34px;padding:0 10px;border:1px solid var(--line);border-radius:17px;background:var(--panel-paper);color:var(--ink);font-size:12px;white-space:nowrap}\n.bt{flex:1;min-width:0;font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.scroll{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.scroll>*{flex:none}\n.foot{flex:none}\n\n.hero{padding:10px 12px;border-radius:12px;background:var(--panel-paper);border:1px solid var(--line);border-left:4px solid var(--accent)}\n.hero.st-over{border-left-color:#B4533A}\n.hl{font-size:11px;color:var(--muted)}\n.hd1{font-size:18px;font-weight:700;margin:2px 0 4px;word-break:keep-all;overflow-wrap:anywhere}\n.hrow{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px}\n.hf{font-size:11px;color:var(--muted);min-width:0}\n.hero.st-over .rel{background:#B4533A;color:#FFFFFF}\n.hero.st-today .rel,.hero.st-new .rel{background:var(--accent);color:var(--on-accent)}\n\n.acts{display:flex;flex-wrap:wrap;gap:6px}\n.btn{flex:1 1 auto;min-width:64px;min-height:36px;padding:6px 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);font-size:12px}\n.btn:disabled{opacity:.45;cursor:default}\n.btn.danger{border-color:#B4533A;font-weight:700}\n.sec{font-size:11px;color:var(--muted);font-weight:600;margin-top:2px}\n.hist{display:flex;flex-direction:column;gap:4px}\n.hi{display:flex;justify-content:space-between;gap:8px;padding:6px 10px;border-radius:8px;background:var(--soft);font-size:12px}\n.hi span{min-width:0}\n.ht2{color:var(--muted);flex:none}\n.none{font-size:12px;color:var(--muted);padding:4px 2px}\n\n.fld{display:flex;flex-direction:column;gap:4px;min-width:0}\n.lb{font-size:11px;color:var(--muted);font-weight:600}\n.hint{font-size:11px;color:var(--muted)}\n.in{width:100%;min-width:0;height:36px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:14px}\n.in.num{width:64px;flex:none;text-align:center}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip.pick{cursor:pointer;color:var(--ink);background:var(--soft);min-height:30px;font-size:12px}\n.every{display:flex;flex-wrap:wrap;align-items:center;gap:6px}\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:10px;overflow:hidden}\n.sg{min-width:44px;height:36px;padding:0 10px;border:0;background:var(--panel-paper);color:var(--ink);font-size:13px}\n.sg.on{background:var(--accent);color:var(--on-accent);font-weight:700}\n\n/* 6x3\uff1a\u6a2a\u5411\u5bbd\u5361\uff0c\u884c\u5185\u5de6\u53f3\u5206\u680f */\n.card[data-size=\"6x3\"] .app{padding:10px 12px}\n.card[data-size=\"6x3\"] .add .at,.card[data-size=\"6x6\"] .add .at,.card[data-size=\"3x6\"] .add .at{display:inline}\n.card[data-size=\"6x3\"] .rmain,.card[data-size=\"6x6\"] .rmain{grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:10px}\n.card[data-size=\"6x3\"] .meta,.card[data-size=\"6x6\"] .meta,.card[data-size=\"3x6\"] .meta{display:flex}\n.card[data-size=\"6x3\"] .tr,.card[data-size=\"6x6\"] .tr{flex-direction:column;align-items:flex-end;gap:2px}\n.card[data-size=\"6x3\"] .dfull,.card[data-size=\"6x6\"] .dfull,.card[data-size=\"3x6\"] .dfull{display:inline}\n.card[data-size=\"6x3\"] .dshort,.card[data-size=\"6x6\"] .dshort,.card[data-size=\"3x6\"] .dshort{display:none}\n.card[data-size=\"6x3\"] .meta{flex-direction:row;gap:8px}\n\n/* 3x6\uff1a\u7a84\u9ad8\u5361\uff0c\u6bcf\u9879\u591a\u884c */\n.card[data-size=\"3x6\"] .app{padding:10px}\n.card[data-size=\"3x6\"] .row{padding:8px 8px 8px 12px}\n.card[data-size=\"3x6\"] .go{height:42px}\n\n/* 6x6\uff1a\u5927\u5361\uff0c\u5e26\u7edf\u8ba1\u6761\u4e0e\u66f4\u5927\u5b57\u53f7 */\n.card[data-size=\"6x6\"] .app{padding:14px 16px;gap:10px}\n.card[data-size=\"6x6\"] .ttl{font-size:18px}\n.card[data-size=\"6x6\"] .stats{display:flex}\n.card[data-size=\"6x6\"] .row{padding:10px 10px 10px 16px;gap:10px}\n.card[data-size=\"6x6\"] .nm{font-size:15px}\n.card[data-size=\"6x6\"] .meta{font-size:12px;flex-direction:column}\n.card[data-size=\"6x6\"] .tr{font-size:12px}\n.card[data-size=\"6x6\"] .go{min-width:60px;height:42px;font-size:14px}\n.card[data-size=\"6x6\"] .hd1{font-size:22px}\n\n/* 3x3 \u4e0e 3x6 \u7684\u8be6\u60c5/\u8868\u5355\u7a84\u5c4f\uff1a\u6309\u94ae\u5355\u5217\u66f4\u6613\u70b9 */\n.card[data-size=\"3x3\"] .hd1{font-size:16px}\n.card[data-size=\"3x3\"] .btn{min-width:56px;padding:4px 6px}\n.card[data-size=\"3x3\"] .every{gap:4px}\n";
var WK='日一二三四五六';
function pad(n){return String(n).padStart(2,'0')}
function pd(s){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');return m?new Date(+m[1],+m[2]-1,+m[3]):null}
function fd(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function nowT(){var t=new Date();return pad(t.getHours())+':'+pad(t.getMinutes())}
function listOf(s){return Array.isArray(s&&s.tasks)?s.tasks:[]}
function unitL(u){return u==='w'?'周':u==='m'?'个月':'天'}
function everyL(t){return '每'+t.n+unitL(t.u)}
function addInt(s,n,u){
  var d=pd(s);if(!d)return '';
  if(u==='m'){
    var dd=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);
    var ml=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();
    d.setDate(Math.min(dd,ml));
  }else{
    d.setDate(d.getDate()+n*(u==='w'?7:1));
  }
  return fd(d);
}
function diffDays(a,b){return Math.round((pd(a)-pd(b))/86400000)}
// mode 0 完整(含周几) / 1 简短 M/D / 2 不含周几
function dateL(s,today,mode){
  var d=pd(s);if(!d)return '';
  if(mode===1)return (d.getMonth()+1)+'/'+d.getDate();
  var y=d.getFullYear()!==pd(today).getFullYear()?d.getFullYear()+'年':'';
  var base=y+(d.getMonth()+1)+'月'+d.getDate()+'日';
  return mode===2?base:base+' 周'+WK[d.getDay()];
}
function info(t,today){
  var h=t.hist||[];
  var le=h.length?h[h.length-1]:null;
  if(!le)return {st:'new',next:'',dd:0,rel:'未开始',last:null};
  var nx=addInt(le.d,t.n,t.u);
  var dd=diffDays(nx,today);
  var st=dd<0?'over':dd===0?'today':dd<=2?'soon':'ok';
  var rel=dd<0?'逾期'+(-dd)+'天':dd===0?'今天':dd===1?'明天':'还有'+dd+'天';
  return {st:st,next:nx,dd:dd,rel:rel,last:le};
}
function lastL(le,today){
  return le?'上次 '+dateL(le.d,today,2)+(le.t?' '+le.t:''):'还没做过';
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const today=day();
  const tasks=listOf(state);
  const mapT=(s,id,fn)=>Object.assign({},s,{tasks:listOf(s).map(t=>t.id===id?fn(t):t)});
  const toList={view:'list',id:null,draft:null,ferr:'',err:'',confirmDel:false,busy:false};

  const complete=async(id)=>{
    if(ui.busy)return;
    ui.busy=true;ui.err='';
    try{
      await update(s=>mapT(s,id,t=>Object.assign({},t,{hist:(t.hist||[]).concat([{d:day(),t:nowT()}])})));
    }catch(e){
      ui.err='保存失败，请重试';redraw();
    }
    ui.busy=false;
  };
  const undo=async(id)=>{
    if(ui.busy)return;
    ui.busy=true;ui.err='';
    try{
      await update(s=>mapT(s,id,t=>Object.assign({},t,{hist:(t.hist||[]).slice(0,-1)})));
    }catch(e){
      ui.err='撤销失败，请重试';redraw();
    }
    ui.busy=false;
  };
  const remove=async(id)=>{
    if(ui.busy)return;
    ui.busy=true;
    try{
      await commit(s=>Object.assign({},s,{tasks:listOf(s).filter(t=>t.id!==id)}),toList);
    }catch(e){
      ui.err='删除失败，请重试';ui.confirmDel=false;redraw();
    }
    ui.busy=false;
  };
  const openAdd=()=>{
    ui.view='form';ui.mode='add';ui.id=null;ui.ferr='';ui.err='';
    ui.draft={name:'',n:'7',u:'d',last:''};
    redraw();
  };
  const openEdit=(t)=>{
    ui.view='form';ui.mode='edit';ui.id=t.id;ui.ferr='';ui.err='';
    ui.draft={name:t.name,n:String(t.n),u:t.u,last:''};
    redraw();
  };
  const openDetail=(id)=>{
    ui.view='detail';ui.id=id;ui.confirmDel=false;ui.err='';redraw();
  };
  const goList=()=>{
    ui.view='list';ui.id=null;ui.draft=null;ui.ferr='';ui.err='';ui.confirmDel=false;redraw();
  };


  const errBox=(msg)=>msg?el('div',{class:'err',role:'alert'},'⚠ '+msg):null;

  const listView=()=>{
    const rows=tasks.map(t=>({t:t,i:info(t,today)})).sort((a,b)=>{
      const ka=a.i.next||today,kb=b.i.next||today;
      if(ka!==kb)return ka<kb?-1:1;
      return String(a.t.name).localeCompare(String(b.t.name),'zh');
    });
    let over=0,td=0,nw=0,wk=0;
    rows.forEach(r=>{
      if(r.i.st==='over')over++;
      else if(r.i.st==='today')td++;
      else if(r.i.st==='new')nw++;
      else if(r.i.dd<=7)wk++;
    });
    const due=over+td+nw;
    const sub=!tasks.length?'还没有事项':due?due+' 项待做':'都在计划内';

    const head=el('div',{class:'hd'},
      el('div',{class:'ht'},el('div',{class:'ttl'},'家务记录'),el('div',{class:'sub'},sub)),
      el('button',{type:'button',class:'add','aria-label':'添加事项',onclick:openAdd},
        el('span',{class:'pl'},'+'),el('span',{class:'at'},'添加')));

    const stat=(label,n)=>el('span',{class:'chip'+(n?' on':'')},label+' '+n);
    const stats=tasks.length?el('div',{class:'stats'},stat('逾期',over),stat('今天',td),stat('未开始',nw),stat('7天内',wk)):null;

    const row=(r)=>{
      const t=r.t,i=r.i;
      const nx=i.next
        ?el('span',{class:'nx'},el('span',{class:'dfull'},dateL(i.next,today,0)),el('span',{class:'dshort'},dateL(i.next,today,1)))
        :el('span',{class:'nx'},el('span',{class:'dfull'},'完成后显示下次日期'));
      return el('div',{class:'row st-'+i.st},
        el('button',{type:'button',class:'rmain','aria-label':'查看 '+t.name,onclick:()=>openDetail(t.id)},
          el('span',{class:'tl'},
            el('span',{class:'nm'},t.name),
            el('span',{class:'meta'},el('span',{class:'itv'},everyL(t)),el('span',{class:'lst'},lastL(i.last,today)))),
          el('span',{class:'tr'},el('span',{class:'rel'},i.rel),nx)),
        el('button',{type:'button',class:'go','aria-label':'完成 '+t.name,onclick:()=>complete(t.id)},'完成'));
    };

    let body;
    if(!tasks.length){
      body=el('div',{class:'empty'},
        el('div',{class:'et'},'还没有家务事项'),
        el('div',{class:'ed'},'添加后设定多久做一次，点“完成”记录时间，自动算出下次日期。'),
        el('button',{type:'button',class:'big',onclick:openAdd},'添加第一项'));
    }else{
      body=el('div',{class:'list'},...rows.map(row));
    }
    return el('div',{class:'app'},...[head,stats,errBox(ui.err),body].filter(Boolean));
  };


  const detailView=()=>{
    const t=tasks.find(x=>x.id===ui.id);
    if(!t){ui.view='list';ui.id=null;return listView();}
    const i=info(t,today);
    const hist=(t.hist||[]).slice().reverse();
    const bar=el('div',{class:'bar'},
      el('button',{type:'button',class:'back','aria-label':'返回列表',onclick:goList},'‹ 返回'),
      el('div',{class:'bt'},t.name));
    const hero=el('div',{class:'hero st-'+i.st},
      el('div',{class:'hl'},'下次该做'),
      el('div',{class:'hd1'},i.next?dateL(i.next,today,0):'完成一次后显示'),
      el('div',{class:'hrow'},el('span',{class:'rel'},i.rel),el('span',{class:'hf'},everyL(t)+' · '+lastL(i.last,today))));
    const delRow=ui.confirmDel
      ?el('div',{class:'acts'},
          el('button',{type:'button',class:'btn danger',onclick:()=>remove(t.id)},'确认删除'),
          el('button',{type:'button',class:'btn',onclick:()=>{ui.confirmDel=false;redraw();}},'取消'))
      :el('div',{class:'acts'},
          el('button',{type:'button',class:'btn',onclick:()=>openEdit(t)},'编辑'),
          el('button',{type:'button',class:'btn',disabled:!hist.length,onclick:()=>undo(t.id)},'撤销上次'),
          el('button',{type:'button',class:'btn',onclick:()=>{ui.confirmDel=true;redraw();}},'删除'));
    const hl=hist.length
      ?el('div',{class:'hist'},...hist.map(h=>el('div',{class:'hi'},el('span',{},dateL(h.d,today,0)),el('span',{class:'ht2'},h.t||'补录'))))
      :el('div',{class:'none'},'还没有完成记录');
    const scroll=el('div',{class:'scroll'},...[
      hero,
      el('button',{type:'button',class:'big',onclick:()=>complete(t.id)},'完成这次'),
      errBox(ui.err),
      delRow,
      el('div',{class:'sec'},'完成记录（共 '+hist.length+' 次）'),
      hl].filter(Boolean));
    return el('div',{class:'app'},bar,scroll);
  };

  const formView=()=>{
    const d=ui.draft||(ui.draft={name:'',n:'7',u:'d',last:''});
    const add=ui.mode!=='edit';
    const save=async()=>{
      if(ui.busy)return;
      const name=String(d.name||'').trim();
      const n=Number(d.n);
      let err='';
      if(!name)err='请填写事项名称';
      else if(!(String(d.n).trim()!==''&&Number.isInteger(n)&&n>=1&&n<=999))err='间隔请填 1–999 的整数';
      else if(add&&d.last&&(!pd(d.last)||d.last>today))err='上次完成日期不能晚于今天';
      if(err){ui.ferr=err;redraw();return;}
      ui.busy=true;ui.ferr='';
      try{
        if(add){
          const id=uid();
          const rec={id:id,name:name,n:n,u:d.u||'d',hist:d.last?[{d:d.last,t:''}]:[]};
          await commit(s=>Object.assign({},s,{tasks:listOf(s).concat([rec])}),toList);
        }else{
          const id=ui.id;
          await commit(s=>mapT(s,id,t=>Object.assign({},t,{name:name,n:n,u:d.u||'d'})),
            {view:'detail',id:id,draft:null,ferr:'',err:'',confirmDel:false,busy:false});
        }
      }catch(e){
        ui.ferr='保存失败，请重试';redraw();
      }
      ui.busy=false;
    };
    const nameIn=el('input',{type:'text',class:'in',value:d.name,placeholder:'例如：洗床单',maxlength:'30',
      oninput:e=>{d.name=e.target.value;},onkeydown:e=>{if(e.key==='Enter')save();}});
    const chips=add?el('div',{class:'chips'},...['洗床单','打扫卫生','清理冰箱'].map(x=>
      el('button',{type:'button',class:'chip pick',onclick:()=>{d.name=x;redraw();}},x))):null;
